def solve(lines: list[str]) -> str:
    # Phase 1: Input Parsing and Validation
    blocks = []
    current_block = None
    current_type = None

    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Check if this is a header line
        match = re.match(r'^(TARGET|OVERRIDE)\s+(.+)', line)
        if match:
            block_type = match.group(1)
            block_name = match.group(2)
            if current_block is not None:
                blocks.append(current_block)
            current_block = {
                'type': block_type,
                'name': block_name,
                'directives': {},
                'id': None if block_type == 'TARGET' else block_name
            }
            current_type = block_type
            continue

        # If we're in a block, check if this is a directive line
        if current_block is not None:
            # Check for = separator
            if '=' in line:
                parts = line.split('=', 1)
                if len(parts) != 2:
                    return "PARSE_ERROR"
                key = parts[0].strip()
                value = parts[1].strip()
                # Validate directive key
                if key not in ('Depends', 'Before', 'After', 'Needs', 'Requires', 'Alias', 'Phony'):
                    return "PARSE_ERROR"
                if key == 'Phony':
                    if value not in ('yes', 'no'):
                        return "PARSE_ERROR"
                    current_block['directives'][key] = value
                else:
                    # Split by whitespace for values
                    # Empty value is valid (e.g., Depends = )
                    current_block['directives'][key] = value
            else:
                # Not a directive line
                return "PARSE_ERROR"
        else:
            # Not in a block, but not a header
            return "PARSE_ERROR"

    if current_block is not None:
        blocks.append(current_block)

    # Validate all blocks
    for block in blocks:
        if block['type'] == 'TARGET':
            if len(block['name']) != 1:
                return "PARSE_ERROR"
        elif block['type'] == 'OVERRIDE':
            if len(block['name']) != 1 or block['id'] is None:
                return "PARSE_ERROR"

    # Phase 2: Universe Construction
    # Collect all target names from TARGET and OVERRIDE headers
    defined_targets = set()
    for block in blocks:
        if block['type'] == 'TARGET':
            defined_targets.add(block['name'])
        elif block['type'] == 'OVERRIDE':
            defined_targets.add(block['name'])

    # Collect all referenced targets from directive values
    referenced_targets = set()
    for block in blocks:
        for key, value in block['directives'].items():
            if key in ('Depends', 'Before', 'After', 'Needs', 'Requires', 'Alias'):
                # Split by whitespace
                vals = value.split()
                referenced_targets.update(vals)

    # Universe = defined targets + referenced targets
    universe = defined_targets | referenced_targets

    # Phase 3: Alias Resolution and Canonicalization
    # Build alias graph: A aliases B means A is connected to B
    alias_graph = defaultdict(set)
    for block in blocks:
        if 'Alias' in block['directives']:
            alias_val = block['directives']['Alias']
            alias_targets = alias_val.split()
            for a, b in zip(alias_targets, alias_targets[1:] + [alias_targets[0]]):
                alias_graph[a].add(b)
                alias_graph[b].add(a)

    # Find connected components using BFS
    visited = set()
    components = []
    for target in sorted(universe):
        if target not in visited:
            # BFS to find component
            queue = [target]
            component = {target}
            visited.add(target)
            while queue:
                node = queue.pop(0)
                for neighbor in alias_graph[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        component.add(neighbor)
                        queue.append(neighbor)
            components.append(component)

    # Select canonical name for each component: lexicographically smallest
    canonical = {}
    for component in components:
        canonical_name = min(component)
        for t in component:
            canonical[t] = canonical_name

    # Phase 4: Directive Accumulation
    # Group blocks by canonical name
    block_groups = defaultdict(list)
    for block in blocks:
        canon_name = canonical[block['name']]
        block_groups[canon_name].append(block)

    # Process TARGET blocks in appearance order
    # Then OVERRIDE blocks sorted by id lexicographically
    all_directives = defaultdict(lambda: {
        'Depends': set(),
        'Before': set(),
        'After': set(),
        'Needs': set(),
        'Requires': set(),
        'Phony': 'no'
    })

    # First, process TARGET blocks in appearance order
    target_order = []
    for block in blocks:
        if block['type'] == 'TARGET':
            target_order.append(block)

    for block in target_order:
        canon_name = canonical[block['name']]
        for key, value in block['directives'].items():
            if key in ('Depends', 'Before', 'After', 'Needs', 'Requires'):
                vals = value.split()
                for v in vals:
                    canon_val = canonical.get(v, v)
                    all_directives[canon_name][key].add(canon_val)
            elif key == 'Alias':
                # Already handled in Phase 3
                pass
            elif key == 'Phony':
                all_directives[canon_name]['Phony'] = value

    # Then process OVERRIDE blocks sorted by id
    override_order = []
    for block in blocks:
        if block['type'] == 'OVERRIDE':
            override_order.append((block['id'], block))
    override_order.sort(key=lambda x: x[0])

    for _, block in override_order:
        canon_name = canonical[block['name']]
        for key, value in block['directives'].items():
            if key in ('Depends', 'Before', 'After', 'Needs', 'Requires'):
                vals = value.split()
                for v in vals:
                    canon_val = canonical.get(v, v)
                    all_directives[canon_name][key].add(canon_val)
            elif key == 'Phony':
                all_directives[canon_name]['Phony'] = value

    # Phase 5: Dependency Graph Construction
    # Build directed graph
    # Nodes are canonical target names
    graph = defaultdict(set)

    for target, directives in all_directives.items():
        # Depends = X1 X2 ... → edges: X1 → U, X2 → U, ...
        for v in directives['Depends']:
            graph[v].add(target)
        # Before = Y1 Y2 ... → edges: U → Y1, U → Y2, ...
        for v in directives['Before']:
            graph[target].add(v)
        # After = Z1 Z2 ... → edges: Z1 → U, Z2 → U, ...
        for v in directives['After']:
            graph[v].add(target)
        # Needs = W1 W2 ... → edges: U → W1, U → W2, ...
        for v in directives['Needs']:
            graph[target].add(v)
        # Requires = V1 V2 ... → edges: U → V1, U → V2, ...
        for v in directives['Requires']:
            graph[target].add(v)

    # Phase 6: Cycle Detection
    # Find all SCCs using Tarjan's algorithm
    index_counter = [0]
    stack = []
    lowlink = {}
    index = {}
    on_stack = {}
    sccs = []

    def strongconnect(v):
        index[v] = index_counter[0]
        lowlink[v] = index_counter[0]
        index_counter[0] += 1
        stack.append(v)
        on_stack[v] = True

        for w in graph[v]:
            if w not in index:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif on_stack.get(w, False):
                lowlink[v] = min(lowlink[v], index[w])

        if lowlink[v] == index[v]:
            scc = []
            while True:
                w = stack.pop()
                on_stack[w] = False
                scc.append(w)
                if w == v:
                    break
            sccs.append(scc)

    for v in universe:
        if v not in index:
            strongconnect(v)

    # Phase 6: Determine cycles
    # A cycle is:
    # - An SCC with size ≥ 2 (multiple nodes)
    # - An SCC with size = 1 containing a self-loop
    cycles = []
    for scc in sccs:
        if len(scc) >= 2:
            cycles.append(sorted(scc))
        elif len(scc) == 1:
            node = scc[0]
            # Check if node has a self-loop
            if node in graph and node in graph[node]:
                cycles.append(sorted(scc))

    # Sort cycles lexicographically
    cycles.sort()

    # Phase 7: Topological Ordering
    # Build condensation DAG
    # Each SCC is a node, edges between components if any node in one component has edge to any node in another
    # First, map each node to its SCC representative
    scc_map = {}
    for scc in sccs:
        for node in scc:
            scc_map[node] = scc

    # Build condensation DAG
    condensation = defaultdict(set)
    for node in universe:
        for neighbor in graph[node]:
            if scc_map[node] != scc_map[neighbor]:
                condensation[scc_map[node]].add(scc_map[neighbor])

    # Topological sort with deterministic tie-breaking
    # For each component, use lexicographically smallest target name as representative
    # Always process component with lexicographically smallest representative first
    # Within each component, sort targets lexicographically

    # Get sorted list of components by their representative
    component_reps = []
    for scc in sccs:
        rep = min(scc)
        component_reps.append((rep, sorted(scc)))
    component_reps.sort(key=lambda x: x[0])

    # Kahn's algorithm with deterministic tie-breaking
    # Compute in-degree for each component
    in_degree = defaultdict(int)
    for comp in component_reps:
        in_degree[comp[0]] = 0
    for comp_from, neighbors in condensation.items():
        for comp_to in neighbors:
            if comp_from != comp_to:
                in_degree[comp_to] += 1

    # Initialize queue with components having in_degree 0
    queue = deque()
    for rep, members in component_reps:
        if in_degree[rep] == 0:
            queue.append(rep)

    # Sort queue by representative
    queue = sorted(queue)

    order = []
    while queue:
        # Process component with lexicographically smallest representative
        current_rep = queue[0]
        queue.pop(0)
        order.append(current_rep)

        # Find all components that current component points to
        # and reduce their in_degree
        for comp in component_reps:
            if comp[0] in condensation.get(current_rep, set()):
                in_degree[comp[0]] -= 1

        # Re-sort queue by representative
        queue = sorted(queue)
        # Also add any new components that have in_degree 0
        for comp in component_reps:
            if comp[0] not in queue and in_degree[comp[0]] == 0:
                queue.append(comp[0])
        queue = sorted(queue)

    # Expand order to individual target names
    final_order = []
    for rep in order:
        final_order.extend(component_reps[rep][1])

    # Phase 8: Output
    result = {
        "order": final_order,
        "cycles": cycles
    }
    return json.dumps(result)
