                condensation[scc_map[node]].add(scc_map[neighbor])

    component_reps = []
    for scc in sccs:
        rep = min(scc)
        component_reps.append((rep, sorted(scc)))
    component_reps.sort(key=lambda x: x[0])

    in_degree = defaultdict(int)
    for comp in component_reps:
