    order = []
    while queue:
        current_rep = queue[0]
        queue.pop(0)
        order.append(current_rep)
        for comp in component_reps:
            if comp[0] in condensation.get(current_rep, set()):
                in_degree[comp[0]] -= 1
        queue = sorted(queue)
        for comp in component_reps:
            if comp[0] not in queue and in_degree[comp[0]] == 0:
                queue.append(comp[0])
        queue = sorted(queue)

    final_order = []
    for rep in order:
